-- V1__create_initial_schema.sql
-- Property Rental Platform: initial database schema
-- UUID values are generated by the application.


-- IDENTITY
CREATE TABLE users (
    id UUID PRIMARY KEY,
    full_name VARCHAR(150) NOT NULL,
    email VARCHAR(254) NOT NULL UNIQUE,
    password_hash VARCHAR(255),
    phone_number VARCHAR(30),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_users_email_not_blank
    CHECK (LENGTH(TRIM(email)) > 0)
);

CREATE TABLE roles (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE user_roles (
    user_id UUID NOT NULL,
    role_id SMALLINT NOT NULL,
    PRIMARY KEY (user_id, role_id),
    CONSTRAINT fk_user_roles_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_user_roles_role
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE RESTRICT
);

CREATE TABLE external_identities (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    provider VARCHAR(50) NOT NULL,
    provider_subject VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_external_identity_provider_subject
    UNIQUE (provider, provider_subject),
    CONSTRAINT fk_external_identity_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_external_identities_user_id
    ON external_identities(user_id);


-- LOCATION
CREATE TABLE provinces (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(10) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE cities (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    province_id SMALLINT NOT NULL,
    name VARCHAR(150) NOT NULL,
    CONSTRAINT uq_cities_province_name UNIQUE (province_id, name),
    CONSTRAINT uq_cities_id_province UNIQUE (id, province_id),
    CONSTRAINT fk_cities_province
    FOREIGN KEY (province_id) REFERENCES provinces(id) ON DELETE RESTRICT
);

CREATE TABLE suburbs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city_id BIGINT NOT NULL,
    name VARCHAR(150) NOT NULL,
    CONSTRAINT uq_suburbs_city_name UNIQUE (city_id, name),
    CONSTRAINT uq_suburbs_id_city UNIQUE (id, city_id),
    CONSTRAINT fk_suburbs_city
    FOREIGN KEY (city_id) REFERENCES cities(id) ON DELETE RESTRICT
);


-- LISTING LOOKUP TABLES
CREATE TABLE property_types (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE listing_statuses (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE unit_types (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE availability_statuses (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE facilities (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);


-- PROPERTIES
CREATE TABLE properties (
    id UUID PRIMARY KEY,
    owner_id UUID NOT NULL,
    property_type_id SMALLINT NOT NULL,
    listing_status_id SMALLINT NOT NULL,
    province_id SMALLINT NOT NULL,
    city_id BIGINT NOT NULL,
    suburb_id BIGINT,
    title VARCHAR(200) NOT NULL,
    description TEXT,
    street_address VARCHAR(255),
    postal_code VARCHAR(20),
    latitude NUMERIC(9,6),
    longitude NUMERIC(9,6),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_properties_title_not_blank
        CHECK (LENGTH(TRIM(title)) > 0),
    CONSTRAINT chk_properties_latitude
        CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
    CONSTRAINT chk_properties_longitude
        CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),

    CONSTRAINT fk_properties_owner
        FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT fk_properties_type
        FOREIGN KEY (property_type_id) REFERENCES property_types(id) ON DELETE RESTRICT,
    CONSTRAINT fk_properties_listing_status
        FOREIGN KEY (listing_status_id) REFERENCES listing_statuses(id) ON DELETE RESTRICT,
    CONSTRAINT fk_properties_city_province
        FOREIGN KEY (city_id, province_id)
            REFERENCES cities(id, province_id) ON DELETE RESTRICT,
    CONSTRAINT fk_properties_suburb_city
        FOREIGN KEY (suburb_id, city_id)
            REFERENCES suburbs(id, city_id) ON DELETE RESTRICT
);

CREATE INDEX idx_properties_owner ON properties(owner_id);
CREATE INDEX idx_properties_location ON properties(province_id, city_id, suburb_id);
CREATE INDEX idx_properties_status ON properties(listing_status_id);
CREATE INDEX idx_properties_type ON properties(property_type_id);


-- RENTAL UNITS
-- A property must have at least one unit before it is
-- published. Enforce this in the application workflow.
CREATE TABLE rental_units (
    id UUID PRIMARY KEY,
    property_id UUID NOT NULL,
    unit_type_id SMALLINT NOT NULL,
    availability_status_id SMALLINT NOT NULL,
    name VARCHAR(150) NOT NULL,
    description TEXT,
    monthly_rent NUMERIC(12,2) NOT NULL,
    available_from DATE,
    is_furnished BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

  CONSTRAINT chk_rental_units_name_not_blank
      CHECK (LENGTH(TRIM(name)) > 0),
  CONSTRAINT chk_rental_units_monthly_rent
      CHECK (monthly_rent >= 0),

  CONSTRAINT fk_rental_units_property
      FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE RESTRICT,
  CONSTRAINT fk_rental_units_type
      FOREIGN KEY (unit_type_id) REFERENCES unit_types(id) ON DELETE RESTRICT,
  CONSTRAINT fk_rental_units_availability
      FOREIGN KEY (availability_status_id)
          REFERENCES availability_statuses(id) ON DELETE RESTRICT
);

CREATE INDEX idx_rental_units_property ON rental_units(property_id);
CREATE INDEX idx_rental_units_availability
    ON rental_units(availability_status_id);
CREATE INDEX idx_rental_units_rent ON rental_units(monthly_rent);


-- MEDIA
CREATE TABLE property_images (
    id UUID PRIMARY KEY,
    property_id UUID NOT NULL,
    image_url TEXT NOT NULL,
    alt_text VARCHAR(255),
    display_order INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT chk_property_images_display_order CHECK (display_order >= 0),
    CONSTRAINT fk_property_images_property
     FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE
);

CREATE INDEX idx_property_images_property
    ON property_images(property_id, display_order);

CREATE TABLE unit_images (
    id UUID PRIMARY KEY,
    rental_unit_id UUID NOT NULL,
    image_url TEXT NOT NULL,
    alt_text VARCHAR(255),
    display_order INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT chk_unit_images_display_order CHECK (display_order >= 0),
    CONSTRAINT fk_unit_images_unit
     FOREIGN KEY (rental_unit_id) REFERENCES rental_units(id) ON DELETE CASCADE
);

CREATE INDEX idx_unit_images_unit
    ON unit_images(rental_unit_id, display_order);


-- FACILITIES
CREATE TABLE property_facilities (
    property_id UUID NOT NULL,
    facility_id SMALLINT NOT NULL,
    PRIMARY KEY (property_id, facility_id),
    CONSTRAINT fk_property_facilities_property
     FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE,
    CONSTRAINT fk_property_facilities_facility
     FOREIGN KEY (facility_id) REFERENCES facilities(id) ON DELETE RESTRICT
);

CREATE TABLE unit_facilities (
    rental_unit_id UUID NOT NULL,
    facility_id SMALLINT NOT NULL,
    PRIMARY KEY (rental_unit_id, facility_id),
    CONSTRAINT fk_unit_facilities_unit
     FOREIGN KEY (rental_unit_id) REFERENCES rental_units(id) ON DELETE CASCADE,
    CONSTRAINT fk_unit_facilities_facility
     FOREIGN KEY (facility_id) REFERENCES facilities(id) ON DELETE RESTRICT
);


-- INQUIRIES
CREATE TABLE inquiry_statuses (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE inquiries (
    id UUID PRIMARY KEY,
    rental_unit_id UUID NOT NULL,
    sender_id UUID NOT NULL,
    inquiry_status_id SMALLINT NOT NULL,
    message TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_inquiries_message_not_blank
       CHECK (LENGTH(TRIM(message)) > 0),
    CONSTRAINT fk_inquiries_unit
       FOREIGN KEY (rental_unit_id) REFERENCES rental_units(id) ON DELETE RESTRICT,
    CONSTRAINT fk_inquiries_sender
       FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT fk_inquiries_status
       FOREIGN KEY (inquiry_status_id) REFERENCES inquiry_statuses(id) ON DELETE RESTRICT
);

CREATE INDEX idx_inquiries_unit ON inquiries(rental_unit_id);
CREATE INDEX idx_inquiries_sender ON inquiries(sender_id);
CREATE INDEX idx_inquiries_status ON inquiries(inquiry_status_id);

CREATE TABLE favourites (
    user_id UUID NOT NULL,
    rental_unit_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, rental_unit_id),
    CONSTRAINT fk_favourites_user
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_favourites_unit
        FOREIGN KEY (rental_unit_id) REFERENCES rental_units(id) ON DELETE CASCADE
);

CREATE INDEX idx_favourites_unit ON favourites(rental_unit_id);


-- MODERATION
CREATE TABLE report_reasons (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE report_statuses (
    id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE listing_reports (
    id UUID PRIMARY KEY,
    reporter_id UUID NOT NULL,
    property_id UUID,
    rental_unit_id UUID,
    reason_id SMALLINT NOT NULL,
    report_status_id SMALLINT NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_listing_reports_single_target
    CHECK (
    (property_id IS NOT NULL AND rental_unit_id IS NULL)
     OR
    (property_id IS NULL AND rental_unit_id IS NOT NULL)
    ),
    CONSTRAINT fk_listing_reports_reporter
    FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT fk_listing_reports_property
    FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE RESTRICT,
    CONSTRAINT fk_listing_reports_unit
    FOREIGN KEY (rental_unit_id) REFERENCES rental_units(id) ON DELETE RESTRICT,
    CONSTRAINT fk_listing_reports_reason
    FOREIGN KEY (reason_id) REFERENCES report_reasons(id) ON DELETE RESTRICT,
    CONSTRAINT fk_listing_reports_status
    FOREIGN KEY (report_status_id) REFERENCES report_statuses(id) ON DELETE RESTRICT
);

CREATE INDEX idx_listing_reports_reporter ON listing_reports(reporter_id);
CREATE INDEX idx_listing_reports_property ON listing_reports(property_id);
CREATE INDEX idx_listing_reports_unit ON listing_reports(rental_unit_id);
CREATE INDEX idx_listing_reports_status ON listing_reports(report_status_id);
